class DictionaryPanel{constructor(){this.wordListEl=document.getElementById("wordList"),this.searchInputEl=document.getElementById("searchInput"),this.addWordBtnEl=document.getElementById("addWordBtn"),this.newWordKanjiEl=document.getElementById("newWordKanji"),this.newWordReadingEl=document.getElementById("newWordReading"),this.wordCountEl=document.getElementById("wordCount"),this.words=[],this.filter="",this.init()}async init(){this.bindEvents(),await this.loadDictionary()}bindEvents(){this.searchInputEl.addEventListener("input",t=>{this.filter=t.target.value.toLowerCase(),this.renderWordList()}),this.addWordBtnEl.addEventListener("click",()=>this.addWord())}async loadDictionary(){try{const t=(await chrome.storage.sync.get("wingdings_dictionary")).wingdings_dictionary||{words:{}};this.words=Object.entries(t.words).map(([t,e])=>({kanji:t,reading:e.reading,romaji:e.romaji})).sort((t,e)=>t.kanji.localeCompare(e.kanji,"ja")),this.renderWordList(),this.wordCountEl.textContent=this.words.length}catch(t){console.error("Error loading dictionary:",t),this.wordListEl.innerHTML='<div class="word-item">辞書の読み込み中にエラーが発生しました。</div>'}}renderWordList(){this.wordListEl.innerHTML="";const t=this.words.filter(t=>t.kanji.toLowerCase().includes(this.filter)||t.reading.toLowerCase().includes(this.filter)||t.romaji.toLowerCase().includes(this.filter));0===t.length&&(this.wordListEl.innerHTML='<div class="word-item">該当する単語はありません。</div>');for(const e of t){const t=document.createElement("div");t.className="word-item",t.innerHTML=`\n            <div class="word-display">\n                <span class="word-kanji">${e.kanji}</span>\n                <span class="word-reading">${e.reading} (${e.romaji})</span>\n            </div>\n            <button class="delete-btn" data-kanji="${e.kanji}">削除</button>\n        `,this.wordListEl.appendChild(t)}this.wordCountEl.textContent=this.words.length,this.wordListEl.querySelectorAll(".delete-btn").forEach(t=>{t.addEventListener("click",t=>this.deleteWord(t.target.dataset.kanji))})}async addWord(){const t=this.newWordKanjiEl.value.trim(),e=this.newWordReadingEl.value.trim();if(t&&e)try{const i=this.convertToRomaji(e),n=await chrome.runtime.sendMessage({type:"ADD_TO_DICTIONARY",kanji:t,reading:e,romaji:i});n&&n.success?(await this.loadDictionary(),this.newWordKanjiEl.value="",this.newWordReadingEl.value=""):alert("単語の追加に失敗しました: "+n?.error)}catch(t){console.error("Error adding word:",t),alert("単語の追加中にエラーが発生しました。")}else alert("単語とよみを両方入力してください。")}convertToRomaji(t){const e={キャ:"KYA",キュ:"KYU",キョ:"KYO",シャ:"SHA",シュ:"SHU",ショ:"SHO",シェ:"SHE",チャ:"CHA",チュ:"CHU",チョ:"CHO",チェ:"CHE",ニャ:"NYA",ニュ:"NYU",ニョ:"NYO",ヒャ:"HYA",ヒュ:"HYU",ヒョ:"HYO",ミャ:"MYA",ミュ:"MYU",ミョ:"MYO",リャ:"RYA",リュ:"RYU",リョ:"RYO",ギャ:"GYA",ギュ:"GYU",ギョ:"GYO",ジャ:"JA",ジュ:"JU",ジョ:"JO",ジェ:"JE",ビャ:"BYA",ビュ:"BYU",ビョ:"BYO",ピャ:"PYA",ピュ:"PYU",ピョ:"PYO",ア:"A",イ:"I",ウ:"U",エ:"E",オ:"O",カ:"KA",キ:"KI",ク:"KU",ケ:"KE",コ:"KO",ガ:"GA",ギ:"GI",グ:"GU",ゲ:"GE",ゴ:"GO",サ:"SA",シ:"SHI",ス:"SU",セ:"SE",ソ:"SO",ザ:"ZA",ジ:"JI",ズ:"ZU",ゼ:"ZE",ゾ:"ZO",タ:"TA",チ:"CHI",ツ:"TSU",テ:"TE",ト:"TO",ダ:"DA",デ:"DE",ド:"DO",ナ:"NA",ニ:"NI",ヌ:"NU",ネ:"NE",ノ:"NO",ハ:"HA",ヒ:"HI",フ:"FU",ヘ:"HE",ホ:"HO",バ:"BA",ビ:"BI",ブ:"BU",ベ:"BE",ボ:"BO",パ:"PA",ピ:"PI",プ:"PU",ペ:"PE",ポ:"PO",マ:"MA",ミ:"MI",ム:"MU",メ:"ME",モ:"MO",ヤ:"YA",ユ:"YU",ヨ:"YO",ラ:"RA",リ:"RI",ル:"RU",レ:"RE",ロ:"RO",ワ:"WA",ン:"N",ッ:"",ー:"-"};let i="",n=t.replace(/[ぁ-ゔ]/g,t=>String.fromCharCode(t.charCodeAt(0)+96));for(let t=0;t<n.length;t++){let r=n.substring(t,t+2);if(e[r]){i+=e[r],t++;continue}let a=n[t];if("ッ"===a){let r=n[t+1];if(r&&e[r]){let t=e[r][0];"N"!==t&&(i+=t)}continue}i+=e[a]||a}return i=i.replace(/([AEIOU])-/g,"$1$1"),i.toUpperCase()}async deleteWord(t){if(confirm(`「${t}」を辞書から削除しますか？`))try{const e=(await chrome.storage.sync.get("wingdings_dictionary")).wingdings_dictionary||{words:{}};e.words&&e.words[t]?(delete e.words[t],e.metadata=e.metadata||{},e.metadata.entryCount=Object.keys(e.words).length,e.metadata.lastUpdate=Date.now(),await chrome.storage.sync.set({wingdings_dictionary:e}),await this.loadDictionary(),alert("単語を削除しました。")):alert("単語が見つかりませんでした。")}catch(t){console.error("Error deleting word:",t),alert("削除エラー: "+t.message)}}}document.addEventListener("DOMContentLoaded",()=>{new DictionaryPanel});